import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{o,c as r,a8 as l}from"./chunks/vendor-scheduler.BuXoCeGx.js";const d=JSON.parse('{"title":"增强组件总览","description":"面向中后台闭环场景的增强层入口。","frontmatter":{"title":"增强组件总览","description":"面向中后台闭环场景的增强层入口。","outline":"deep"},"headers":[],"relativePath":"pro-components/overview.md","filePath":"pro-components/overview.md","lastUpdated":1779528939000}'),t={name:"pro-components/overview.md"};function n(i,a,p,s,m,c){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="增强组件总览" tabindex="-1">增强组件总览 <a class="header-anchor" href="#增强组件总览" aria-label="Permalink to &quot;增强组件总览&quot;">​</a></h1><p>这里不再把增强层理解成“每一个局部区块都值得公开成一个组件”。收口后的心智是：对外主推少数真正有稳定契约的核心公开件，其余能力通过场景页、页面容器和内部片段来理解。</p><p>如果你是在收后台项目里的页面级样式，先看 <a href="/guide/backend-migration">后台迁移指南</a>，再回到这里挑选增强层入口。</p><h2 id="核心表单与筛选" tabindex="-1">核心表单与筛选 <a class="header-anchor" href="#核心表单与筛选" aria-label="Permalink to &quot;核心表单与筛选&quot;">​</a></h2><ul><li><a href="/pro-components/search-form">SearchForm 搜索表单</a>：统一筛选栏布局、查询动作和折叠字段。</li><li><a href="/pro-components/pro-form">ProForm 增强表单</a>：统一表单网格、标题和动作区。</li><li><a href="/pro-components/overlay-form">OverlayForm 覆盖层表单</a>：统一覆盖层编辑内核。</li><li><a href="/pro-components/dialog-form">DialogForm 弹窗表单</a>：固定弹窗容器的 facade，适合明确的弹窗编辑链路。</li><li><a href="/pro-components/drawer-form">DrawerForm 抽屉表单</a>：固定抽屉容器的 facade，适合保留页面上下文的侧滑编辑链路。</li><li><a href="/pro-components/filter-panel">FilterPanel 筛选面板</a>：统一高级筛选容器。</li><li><a href="/pro-components/request-form">RequestForm 请求表单</a>：统一加载、提交和表单骨架。</li><li><a href="/pro-components/login-form">LoginForm 登录表单</a>：统一认证场景里的登录主链路和第三方登录入口展示。</li><li><a href="/pro-components/steps-form">StepsForm 分步表单</a>：统一多阶段录入流程。</li></ul><h2 id="核心列表与数据" tabindex="-1">核心列表与数据 <a class="header-anchor" href="#核心列表与数据" aria-label="Permalink to &quot;核心列表与数据&quot;">​</a></h2><ul><li><a href="/pro-components/pro-table">ProTable 增强表格</a>：统一工具栏、搜索区、表格本体和分页联动。</li><li><a href="/pro-components/column-setting-panel">ColumnSettingPanel 列设置面板</a>：统一列显隐配置入口。</li><li><a href="/pro-components/saved-view-tabs">SavedViewTabs 视图页签</a>：统一后台常见的视图切换和保存入口。</li><li><a href="/pro-components/table-filter-drawer">TableFilterDrawer 表格筛选抽屉</a>：统一高级筛选抽屉。</li><li><a href="/pro-components/import-result-table">ImportResultTable 导入结果表格</a>：统一导入反馈摘要和结果明细。</li><li><a href="/pro-components/list-page">ListPage 列表页面容器</a>：统一列表页骨架。</li><li><a href="/pro-components/crud-page">CrudPage 增删改查页面</a>：统一列表、编辑和查看闭环。</li></ul><h2 id="核心详情与历史" tabindex="-1">核心详情与历史 <a class="header-anchor" href="#核心详情与历史" aria-label="Permalink to &quot;核心详情与历史&quot;">​</a></h2><ul><li><a href="/pro-components/audit-timeline">AuditTimeline 审计时间线</a>：统一历史记录与审批说明。</li><li><a href="/pro-components/detail-panel">DetailPanel 详情面板</a>：统一覆盖层中的详情查看，不再把抽屉详情和弹窗详情拆成两套主心智。</li><li><a href="/pro-components/detail-page">DetailPage 详情页面容器</a>：统一完整详情页骨架。</li></ul><h2 id="流程与任务" tabindex="-1">流程与任务 <a class="header-anchor" href="#流程与任务" aria-label="Permalink to &quot;流程与任务&quot;">​</a></h2><ul><li><a href="/pro-components/approval-flow-panel">ApprovalFlowPanel 审批流面板</a>：统一审批进度和节点展示。</li><li><a href="/pro-components/import-wizard">ImportWizard 导入向导</a>：统一导入流程步骤。</li><li><a href="/pro-components/export-task-panel">ExportTaskPanel 导出任务面板</a>：统一导出任务状态展示。</li></ul><h2 id="页面布局" tabindex="-1">页面布局 <a class="header-anchor" href="#页面布局" aria-label="Permalink to &quot;页面布局&quot;">​</a></h2><ul><li><a href="/pro-components/page-header">PageHeader 页面头部</a>：统一页面标题、描述、元信息和动作区。</li><li><a href="/pro-components/page-container">PageContainer 页面容器</a>：统一头部、主体内容、footer 和 loading 壳层。</li><li><a href="/pro-components/stat-card">StatCard 指标卡片</a>：统一后台首页和运营面板里的数字指标展示。</li><li><a href="/pro-components/async-state-container">AsyncStateContainer 异步状态容器</a>：统一加载、空态、错误和恢复动作承载。</li><li><a href="/pro-components/split-layout-page">SplitLayoutPage 分栏布局页</a>：统一主从布局与侧栏布局，不再把两种双栏工作区拆成并列主心智。</li></ul><h2 id="当前不再主推为独立公开件" tabindex="-1">当前不再主推为独立公开件 <a class="header-anchor" href="#当前不再主推为独立公开件" aria-label="Permalink to &quot;当前不再主推为独立公开件&quot;">​</a></h2><ul><li>诸如列表头、批量操作条、筛选预设、详情分区、附件区、操作日志区这类能力，后续更适合作为页面容器内部块、slot 片段或场景用法出现。</li><li>当前仓库里仍保留这些页面和实现，但这个总览页不再把它们作为增强层的第一入口。</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li>先看 <a href="/pro-components/search-form">SearchForm 搜索表单</a>、<a href="/pro-components/pro-table">ProTable 增强表格</a> 和 <a href="/pro-components/list-page">ListPage 列表页面容器</a>，理解后台列表页主干。</li><li>再看 <a href="/pro-components/overlay-form">OverlayForm 覆盖层表单</a>、<a href="/pro-components/dialog-form">DialogForm 弹窗表单</a>、<a href="/pro-components/drawer-form">DrawerForm 抽屉表单</a>、<a href="/pro-components/login-form">LoginForm 登录表单</a>、<a href="/pro-components/steps-form">StepsForm 分步表单</a>、<a href="/pro-components/crud-page">CrudPage 增删改查页面</a>，补齐编辑链路。</li><li>接着看 <a href="/pro-components/detail-panel">DetailPanel 详情面板</a>、<a href="/pro-components/detail-page">DetailPage 详情页面容器</a>、<a href="/pro-components/audit-timeline">AuditTimeline 审计时间线</a>，补齐查看和历史记录。</li><li>再看 <a href="/pro-components/page-header">PageHeader 页面头部</a>、<a href="/pro-components/page-container">PageContainer 页面容器</a>、<a href="/pro-components/stat-card">StatCard 指标卡片</a>，补齐页面展示壳层。</li><li>最后看 <a href="/pro-components/approval-flow-panel">ApprovalFlowPanel 审批流面板</a>、<a href="/pro-components/import-wizard">ImportWizard 导入向导</a>、<a href="/pro-components/export-task-panel">ExportTaskPanel 导出任务面板</a>，理解更重的业务流场景。</li><li>然后进入 <a href="/examples/pro/overview">增强组件示例总览</a>，按场景和闭环查看整套接法。</li></ol>',17)])])}const u=e(t,[["render",n]]);export{d as __pageData,u as default};
